/* From Uiverse.io by ahmed150up - Tags: login, form */
.__UIV_SCOPE__ .login-card {
  width: 300px;
  margin: 0 auto;
  padding: 20px;
  border: 1px solid #ccc;
  border-radius: 10px;
  background-color: #e8e8e8;
  box-shadow: 2px 2px 10px #ccc;
}

.__UIV_SCOPE__ .card-header {
  text-align: center;
  margin-bottom: 20px
}

.__UIV_SCOPE__ .card-header .log {
  margin: 0;
  font-size: 24px;
  color: black;
}

.__UIV_SCOPE__ .form-group {
  margin-bottom: 15px;
}

.__UIV_SCOPE__ label {
  font-size: 18px;
  margin-bottom: 5px;
}

.__UIV_SCOPE__ input[type="text"], .__UIV_SCOPE__ input[type="password"] {
  width: 100%;
  padding: 12px 20px;
  font-size: 16px;
  border: 1px solid #ccc;
  border-radius: 4px;
  box-sizing: border-box;
  transition: 0.5s;
}

.__UIV_SCOPE__ input[type="submit"] {
  width: 100%;
  background-color: #333;
  color: white;
  padding: 14px 20px;
  margin: 8px 0;
  border: none;
  border-radius: 4px;
  cursor: pointer;
}

.__UIV_SCOPE__ input[type="submit"]:hover {
  background-color: #ccc;
  color: black;
}
